import PolyText from './poly-text.js';
import { precompileTemplate } from '@ember/template-compilation';
import { setComponentTemplate } from '@ember/component';
import templateOnly from '@ember/component/template-only';

const PolyListItem = setComponentTemplate(precompileTemplate("<PolyText @tag=\"li\" ...attributes>{{yield}}</PolyText>", {
  strictMode: true,
  scope: () => ({
    PolyText
  })
}), templateOnly());

export { PolyListItem as default };
